import React, { useState } from 'react';
import { 
  Typography, 
  List, 
  ListItem, 
  ListItemButton, 
  ListItemText, 
  Divider, 
  Button,
  Box,
  CircularProgress,
  Alert,
  IconButton,
  Tooltip,
  Paper,
} from '@mui/material';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import { useAppSelector, useAppDispatch } from '../../store/hooks';
import { fetchProjectDetails, setCurrentProject } from '../../store/projectSlice';
import { useProjects, useDeleteProject } from '../../services/queries';
import ProjectForm from './ProjectForm';

const ProjectList: React.FC = () => {
  const dispatch = useAppDispatch();
  const { currentProject } = useAppSelector((state) => state.projects);
  const [isFormOpen, setIsFormOpen] = useState(false);

  // Use TanStack Query to fetch projects
  const { data: projects = [], isLoading, error } = useProjects();
  const deleteProjectMutation = useDeleteProject();
  
  const handleSelectProject = (projectId: number) => {
    dispatch(fetchProjectDetails(projectId));
  };

  const handleDeleteProject = async (projectId: number) => {
    const projectName = projects.find((p) => p.id === projectId)?.name || 'this project';
    const confirmed = window.confirm(`Delete ${projectName}? This action cannot be undone.`);
    if (!confirmed) return;
    await deleteProjectMutation.mutateAsync(projectId);
    if (currentProject?.id === projectId) {
      dispatch(setCurrentProject(null));
    }
  };

  const handleOpenForm = () => {
    setIsFormOpen(true);
  };

  const handleCloseForm = () => {
    setIsFormOpen(false);
  };

  let content;

  if (isLoading) {
    content = (
      <Box sx={{ display: 'flex', justifyContent: 'center', my: 4 }}>
        <CircularProgress />
      </Box>
    );
  } else if (error) {
    content = (
      <Alert severity="error">
        Error: {error instanceof Error ? error.message : 'Failed to fetch projects'}
      </Alert>
    );
  } else if (projects.length === 0) {
    content = (
      <Typography color="textSecondary" sx={{ py: 2 }}>
        No projects yet. Create one to get started.
      </Typography>
    );
  } else {
    content = (
      <List>
        {projects.map((project) => (
          <ListItem 
            key={project.id} 
            disablePadding
            secondaryAction={
              <Tooltip title="Delete project">
                <IconButton edge="end" onClick={() => handleDeleteProject(project.id)} size="small">
                  <DeleteOutlineIcon fontSize="small" color="error" />
                </IconButton>
              </Tooltip>
            }
            sx={{ mb: 1 }}
          >
            <ListItemButton
              selected={currentProject?.id === project.id}
              onClick={() => handleSelectProject(project.id)}
              sx={{
                borderRadius: 2,
                px: 2,
                py: 1.5,
                background: currentProject?.id === project.id 
                  ? 'linear-gradient(135deg, rgba(70,130,255,0.25), rgba(70,130,255,0.1))'
                  : 'rgba(255,255,255,0.04)',
                '&:hover': {
                  background: 'linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0.05))',
                },
              }}
            >
              <ListItemText 
                primary={project.name} 
                secondary={project.description} 
                primaryTypographyProps={{ fontWeight: 600 }}
                secondaryTypographyProps={{ color: 'text.secondary' }}
              />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
    );
  }

  return (
    <Paper
      elevation={4}
      sx={{
        p: 2,
        borderRadius: 3,
        background: 'linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02))',
        backdropFilter: 'blur(6px)',
      }}
    >
      <Typography variant="h6" gutterBottom sx={{ fontWeight: 700, letterSpacing: 0.3 }}>
        Projects
      </Typography>
      <Button variant="contained" fullWidth onClick={handleOpenForm} sx={{ mb: 2 }}>
        New Project
      </Button>
      <Divider sx={{ my: 1 }} />
      {content}
      <ProjectForm
        open={isFormOpen}
        onClose={handleCloseForm}
      />
    </Paper>
  );
};

export default ProjectList;

import React, { useState } from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  Box,
  CircularProgress,
} from '@mui/material';
import { useCreateProject } from '../../services/queries';

interface ProjectFormProps {
  open: boolean;
  onClose: () => void;
}

const ProjectForm: React.FC<ProjectFormProps> = ({ open, onClose }) => {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [budget, setBudget] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const createProjectMutation = useCreateProject();

  const handleSubmit = async () => {
    try {
      await createProjectMutation.mutateAsync({
        name,
        description,
        budget: parseFloat(budget),
        start_date: startDate,
        end_date: endDate,
      });
      // Reset form and close
      setName('');
      setDescription('');
      setBudget('');
      setStartDate('');
      setEndDate('');
      onClose();
    } catch (error) {
      console.error('Failed to create project:', error);
    }
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Create New Project</DialogTitle>
      <DialogContent>
        <Box component="form" noValidate autoComplete="off" sx={{ mt: 2 }}>
          <TextField
            label="Project Name"
            fullWidth
            margin="normal"
            value={name}
            onChange={(e) => setName(e.target.value)}
            disabled={createProjectMutation.isPending}
          />
          <TextField
            label="Scope / Description"
            fullWidth
            multiline
            rows={4}
            margin="normal"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            disabled={createProjectMutation.isPending}
          />
          <TextField
            label="Budget"
            type="number"
            fullWidth
            margin="normal"
            value={budget}
            onChange={(e) => setBudget(e.target.value)}
            disabled={createProjectMutation.isPending}
          />
          <TextField
            label="Start Date"
            type="date"
            fullWidth
            margin="normal"
            InputLabelProps={{ shrink: true }}
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            disabled={createProjectMutation.isPending}
          />
          <TextField
            label="End Date"
            type="date"
            fullWidth
            margin="normal"
            InputLabelProps={{ shrink: true }}
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            disabled={createProjectMutation.isPending}
          />
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={createProjectMutation.isPending}>
          Cancel
        </Button>
        <Button 
          onClick={handleSubmit} 
          variant="contained"
          disabled={createProjectMutation.isPending || !name.trim()}
        >
          {createProjectMutation.isPending ? <CircularProgress size={24} /> : 'Create'}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default ProjectForm;

import React from 'react';
import { AppBar, Toolbar, Button, Tooltip, Box } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { useAppSelector } from '../../store/hooks';
import { Task } from '../../types/domain';

const hasCycle = (tasks: Task[]) => {
  const adj = new Map<number, number[]>();
  tasks.forEach((t) => adj.set(t.id, t.predecessors));
  const visiting = new Set<number>();
  const visited = new Set<number>();
  const dfs = (id: number): boolean => {
    if (visiting.has(id)) return true;
    if (visited.has(id)) return false;
    visiting.add(id);
    for (const nei of adj.get(id) || []) {
      if (!adj.has(nei)) continue;
      if (dfs(nei)) return true;
    }
    visiting.delete(id);
    visited.add(id);
    return false;
  };
  for (const id of adj.keys()) {
    if (dfs(id)) return true;
  }
  return false;
};

const SetupFooter: React.FC = () => {
  const navigate = useNavigate();
  const { currentProject, tasks } = useAppSelector((state) => state.projects);
  const normalizedTasks = tasks.map(t => ({
    ...t,
    predecessors: t.predecessors || [],
    duration: t.duration ?? 0,
    text: t.text || '',
  }));

  const hasTasks = normalizedTasks.length > 0;
  const hasValidDurations = normalizedTasks.every(t => t.duration >= 0);
  const hasNames = normalizedTasks.every(t => t.text.trim().length > 0);
  const hasValidPreds = normalizedTasks.every(t => (t.predecessors || []).every(pid => normalizedTasks.some(x => x.id === pid)));
  const noCycles = !hasCycle(normalizedTasks as Task[]);
  const isDataValid = currentProject !== null && hasTasks && hasValidDurations && hasNames && hasValidPreds && noCycles;

  const handleStartSimulation = () => {
    if (isDataValid) {
      navigate(`/simulation/${currentProject.id}`);
    }
  };

  let tooltipText = "Start the simulation";
  if (!currentProject) {
    tooltipText = "Please select a project first.";
  } else if (tasks.length === 0) {
    tooltipText = "The selected project has no tasks.";
  } else if (!hasValidDurations) {
    tooltipText = "One or more tasks have invalid duration.";
  } else if (!hasNames) {
    tooltipText = "One or more tasks are missing a name.";
  } else if (!hasValidPreds) {
    tooltipText = "One or more predecessors reference missing tasks.";
  } else if (!noCycles) {
    tooltipText = "Dependency cycle detected. Please fix predecessors.";
  }
  // This can be expanded with more checks, e.g., for cyclic dependencies.

  return (
    <AppBar position="static" color="default" sx={{ top: 'auto', bottom: 0, borderTop: '1px solid', borderColor: 'divider' }}>
      <Toolbar>
        <Box sx={{ flexGrow: 1 }} />
        <Tooltip title={tooltipText}>
          <span>
            <Button 
              variant="contained" 
              color="secondary" 
              disabled={!isDataValid}
              onClick={handleStartSimulation}
            >
              Start Simulation
            </Button>
          </span>
        </Tooltip>
      </Toolbar>
    </AppBar>
  );
};

export default SetupFooter;

