    } finally {
      setIsCreatingDemo(false);
    }
  };

  const handleOpenForm = () => {
    setIsFormOpen(true);
  };

  const handleCloseForm = () => {
    setIsFormOpen(false);
  };

  let content;

  if (isLoading) {
