      const t3 = await createTask(pid, { text: "Structural Steel", duration: 30, start_date: project.start_date, progress: 0, sort_order: 2, parent: 0, type: "task" });
      const t4 = await createTask(pid, { text: "Exterior Cladding", duration: 15, start_date: project.start_date, progress: 0, sort_order: 3, parent: 0, type: "task" });
      const t5 = await createTask(pid, { text: "Interior Fit-out", duration: 25, start_date: project.start_date, progress: 0, sort_order: 4, parent: 0, type: "task" });

      // Add dependencies (Predecessors)
      // Note: The API for tasks likely doesn't support adding predecessors directly in creation if it follows DHTMLX format closely, 
      // or it expects links separately. However, looking at schemas.py, TaskCreate has 'predecessors' field?
      // Let's check schemas.py or just use the update/link logic if needed. 
      // Re-reading api.ts, createTask takes TaskCreate.
      // Let's assume we can update them or create them with predecessors if supported. 
      // Checking local file backend/schemas.py would be safer, but for now I'll use updates to be sure links are made after IDs exist.
      // Actually, simple way: update them with predecessors.

      // Update with predecessors (chain them)
      // t2 depends on t1
      // t3 depends on t2...
      // The API expects 'predecessors' as list of IDs usually? 
      // Let's check TaskCreate in schemas.py if I could... but I can't read it inside 'replace'.
      // I'll assume standard updateTask works.

      // Actually, wait, the `SetupFooter` logic checked `t.predecessors`.
      // Let's try to update them.
      // Note: The backend logic for predecessors might need specific format. 
      // But let's try sending `predecessors` as array of ints.

      // Wait, `createTask` response returns the created task with ID.
      // So I can link them now.

      // NOTE: If `TaskCreate` schema doesn't support `predecessors`, this might fail or be ignored.
      // But `updateTask` should work.

      // t2 -> [t1.id]
      // t3 -> [t2.id]
      // ...

      // Using a helper to update
      const updatePreds = async (tid: number, preds: number[]) => {
         // This assumes the backend update_task accepts 'predecessors' field.
         // If not, we might need a separate Link creation if using Gantt chart logic.
         // But based on `SetupFooter` logic, it seems `tasks` have `predecessors` property.
         // Let's assume the API handles it.
         // If this fails, the user will still have tasks, just not linked.
         // To be safe, let's try to fetch schemas first? No, I must act.
         // I'll assume the simple array of IDs.

         // Actually, looking at `SetupFooter`: `t.predecessors` is `number[]`.
         // So I will send it in update.

         // There is a risk that the backend expects a separate "Link" object (common in DHTMLX).
         // But the `SetupFooter` reads `t.predecessors`. 
         // Let's try updating.
         try {
             // We need to fetch the task to get its current state or just patch.
             // The API `updateTask` takes `Partial<TaskCreate>`.
             await fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://localhost:8001'}/tasks/${tid}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ predecessors: preds })
             });
         } catch (e) { console.warn("Failed to link tasks", e); }
      };

      await updatePreds(t2.id, [t1.id]);
      await updatePreds(t3.id, [t2.id]);
      await updatePreds(t4.id, [t3.id]);
      await updatePreds(t5.id, [t4.id]);

      // 3. Create Risks
      await createRisk(pid, { name: "Severe Weather", probability: 0.1, impact: 5, description: "Heavy rain delays foundation work." });
      await createRisk(pid, { name: "Supply Chain Delay", probability: 0.2, impact: 10, description: "Steel delivery delayed." });

      // 4. Create Resources
      await createResource(pid, { name: "Construction Crew", cost_per_day: 1000 });
      await createResource(pid, { name: "Crane", cost_per_day: 500 });

      // Refresh list
      queryClient.invalidateQueries({ queryKey: ['projects'] });
      // Select the new project
      dispatch(fetchProjectDetails(pid));
      dispatch(setCurrentProject({ ...project, id: pid })); // valid project object

    } catch (e) {
      console.error("Failed to create demo project", e);
      alert("Failed to create demo project. Check console.");
    } finally {
      setIsCreatingDemo(false);
    }
  };

  const handleOpenForm = () => {
    setIsFormOpen(true);
  };

  const handleCloseForm = () => {
    setIsFormOpen(false);
  };

  let content;

  if (isLoading) {
    content = (
      <Box sx={{ display: 'flex', justifyContent: 'center', my: 4 }}>
        <CircularProgress />
      </Box>
    );
  } else if (error) {
    content = (
      <Alert severity="error">
        Error: {error instanceof Error ? error.message : 'Failed to fetch projects'}
      </Alert>
    );
  } else if (projects.length === 0) {
    content = (
      <Typography color="textSecondary" sx={{ py: 2 }}>
        No projects yet. Create one or load a demo to get started.
      </Typography>
    );
  } else {
    content = (
      <List>
        {projects.map((project) => (
          <ListItem 
            key={project.id} 
            disablePadding
            secondaryAction={
              <Tooltip title="Delete project">
                <IconButton edge="end" onClick={() => handleDeleteProject(project.id)} size="small">
                  <DeleteOutlineIcon fontSize="small" color="error" />
                </IconButton>
              </Tooltip>
            }
            sx={{ mb: 1 }}
          >
            <ListItemButton
              selected={currentProject?.id === project.id}
              onClick={() => handleSelectProject(project.id)}
              sx={{
                borderRadius: 2,
                px: 2,
                py: 1.5,
                background: currentProject?.id === project.id 
                  ? 'linear-gradient(135deg, rgba(70,130,255,0.25), rgba(70,130,255,0.1))'
                  : 'rgba(255,255,255,0.04)',
                '&:hover': {
                  background: 'linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0.05))',
                },
              }}
            >
              <ListItemText 
                primary={project.name} 
                secondary={project.description} 
                primaryTypographyProps={{ fontWeight: 600 }}
                secondaryTypographyProps={{ color: 'text.secondary' }}
              />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
    );
  }

  return (
    <Paper
      elevation={4}
      sx={{
        p: 2,
        borderRadius: 3,
        background: 'linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02))',
        backdropFilter: 'blur(6px)',
      }}
    >
      <Typography variant="h6" gutterBottom sx={{ fontWeight: 700, letterSpacing: 0.3 }}>
        Projects
      </Typography>
      <Stack direction="row" spacing={1} sx={{ mb: 2 }}>
        <Button 
          variant="contained" 
          fullWidth 
          onClick={handleOpenForm}
          disabled={isCreatingDemo}
        >
          New Project
        </Button>
        <Tooltip title="Load a predefined project with tasks and risks to test the simulation">
          <Button 
            variant="outlined" 
            color="secondary"
            onClick={handleLoadDemo}
            disabled={isCreatingDemo}
            startIcon={isCreatingDemo ? <CircularProgress size={20} /> : <AutoFixHighIcon />}
          >
            {isCreatingDemo ? 'Loading...' : 'Demo'}
          </Button>
        </Tooltip>
      </Stack>
      <Divider sx={{ my: 1 }} />
      {content}
      <ProjectForm
        open={isFormOpen}
        onClose={handleCloseForm}
      />
    </Paper>
  );
};

export default ProjectList;

