export interface Project {
  id: number;
  name: string;
  description: string;
  budget: number;
  contingency: number; // Percentage
}

export interface Task {
  id: number; // Unique ID for the task, now a number from backend
  text: string; // Name/description of the task
  start_date: string; // YYYY-MM-DD format
  duration: number; // in days
  progress: number; // 0 to 1
  parent: number | null; // ID of the parent task, now a number or null
  predecessors: number[]; // Array of task IDs this task depends on, now numbers
  cost: number;
  resource_id?: number; // Assuming resource IDs are numbers
  project_id: number; // Project ID foreign key
}

export interface Resource {
  id: number; // Assuming resource IDs are numbers
  name: string;
  cost_per_day: number;
}

export type RiskLikelihood = 'Low' | 'Medium' | 'High';
export type RiskImpact = 'Low' | 'Medium' | 'High';

export interface Risk {
  id: number; // Assuming risk IDs are numbers
  description: string;
  likelihood: RiskLikelihood;
  impact: RiskImpact;
  // Probability is derived from likelihood, e.g., Low=0.1, Medium=0.3, High=0.6
  probability: number; 
  // Cost impact is derived from impact level, e.g., Low=5000, Medium=20000, High=50000
  cost_impact: number;
  // Duration impact in days
  duration_impact: number; 
  affected_task_ids: number[]; // Now numbers
}

export interface SimulationRun {
  id: number;
  project_id: number;
  status: string;
  created_at: string;
  started_at?: string | null;
  completed_at?: string | null;
  total_duration?: number | null;
  total_cost?: number | null;
  critical_path?: number[];
  results?: SimulationResults | null;
}

export interface SimulationResults {
  total_duration?: number;
  total_cost?: number;
  tasks_completed?: number;
  risk_events?: number;
  event_count?: number;
  base_duration?: number;
  critical_path?: number[];
  timeline?: { day: number; active: number; completed: number }[];
  p80_cost?: number; // optional future fields
  p80_duration?: number;
  base_cost?: number;
  mean_duration?: number;
  std_dev_duration?: number;
  p50_duration?: number;
  p90_duration?: number;
  mean_cost?: number;
  std_dev_cost?: number;
  p50_cost?: number;
  p90_cost?: number;
  iterations?: number;
  duration_distribution?: number[];
  bin_edges_duration?: number[];
  cost_distribution?: number[];
  bin_edges_cost?: number[];
  ai_assessment?: string;
  ai_recommendations?: string[];
  finalCost?: number;
  finalDuration?: number;
  risksOccurred?: number;
}

// Data structure for the Gantt chart
export interface GanttTask {
    id: number;
    start_date: string;
    text: string;
    duration: number;
    progress: number;
    parent?: number | null; // Now number or null
    cost?: number;
    // DHTMLX Gantt specific fields
    type?: string; 
    open?: boolean;
}

export interface GanttLink {
    id: number;
    source: number;
    target: number;
    type: string; // e.g., '0' for finish_to_start
}

// For simulation logs
export type SimulationEventType =
  | 'TASK_START'
  | 'TASK_END'
  | 'RISK_EVENT'
  | 'SIM_START'
  | 'SIM_END'
  | 'task_started'
  | 'task_completed'
  | 'simulation_completed'
  | 'connected'
  | 'pong';

export interface SimulationEvent {
    timestamp: string | number;
    type?: SimulationEventType | string;
    event_type?: SimulationEventType | string;
    message?: string;
    task_id?: number;
    risk_id?: number;
    details?: Record<string, unknown>;
}

// For KPIs
export interface KpiValues {
    pv: number; // Planned Value
    ev: number; // Earned Value
    ac: number; // Actual Cost
    sv: number; // Schedule Variance (EV - PV)
    cv: number; // Cost Variance (EV - AC)
    rei: number; // Risk Exposure Index
}

export interface ProjectCreate {
  name: string;
  description: string;
  budget: number;
  start_date: string;
  end_date: string;
}

export interface ProjectUpdate extends Partial<ProjectCreate> {
  contingency?: number;
}

export interface TaskCreate {
  text: string;
  start_date: string;
  duration: number;
  progress?: number;
  parent?: number | null;
  cost?: number;
  predecessors?: number[];
  dependencies?: number[]; // backend naming
  resource_id?: number;
}

export interface TaskUpdate extends Partial<TaskCreate> {}

export interface RiskCreate {
  description: string;
  likelihood?: 'Low' | 'Medium' | 'High';
  impact?: 'Low' | 'Medium' | 'High';
  probability?: number;
  cost_impact?: number;
  duration_impact?: number;
  affected_task_ids: number[];
}

export interface RiskUpdate extends Partial<RiskCreate> {}

