          </Button>
        </Tooltip>
      </Stack>
      <Divider sx={{ my: 1 }} />
      {content}
      <ProjectForm
        open={isFormOpen}
        onClose={handleCloseForm}
      />
    </Paper>
  );
};

export default ProjectList;

