import React, { useEffect, useState } from 'react';
import { Box, Paper, Typography, Tabs, Tab } from '@mui/material';
import { useParams, useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../store/hooks';
import { fetchProjectDetails } from '../store/projectSlice';
import * as api from '../services/api';
import { startSimulation as startSimAction, pushEvent, applyTaskEvent, simulationError } from '../store/simulationSlice';
import SimulationControls from '../components/simulation/SimulationControls';
import GanttPanel from '../components/simulation/GanttPanel';
import KpiDashboard from '../components/simulation/KpiDashboard';
import EventLog from '../components/simulation/EventLog';
import { useWebSocket } from '../services/websocket';
import { fetchSimulationResult } from '../store/projectSlice';

// (TabPanel component remains the same)
interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;
  return (
    <div role="tabpanel" hidden={value !== index} {...other}>
      {value === index && <Box sx={{ p: 2, height: '100%', overflowY: 'auto' }}>{children}</Box>}
    </div>
  );
}

const SimulationPage: React.FC = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { currentProject, tasks, status: projectStatus } = useAppSelector((state) => state.projects);
  const simStatus = useAppSelector(state => state.simulation.status);
  const simTasks = useAppSelector(state => state.simulation.tasks);
  const [tabValue, setTabValue] = useState(0);
  const simulationId = useAppSelector(state => state.simulation.simulationId);
  const [, setPolling] = useState<ReturnType<typeof setInterval> | null>(null);

  // Effect to fetch initial data
  useEffect(() => {
    if (!projectId) {
      navigate('/');
      return;
    }
    const numericId = Number(projectId);
    if (!currentProject || currentProject.id !== numericId) {
      dispatch(fetchProjectDetails(numericId));
    }
  }, [projectId, dispatch, navigate, currentProject]);

  // Effect to auto-start simulation once project is loaded
  useEffect(() => {
     const numericId = projectId ? Number(projectId) : null;
     if (projectStatus === 'succeeded' && numericId !== null && currentProject?.id === numericId && simStatus === 'idle') {
      api.runSimulation(numericId).then(res => {
        dispatch(startSimAction({ simulationId: res.simulation_run_id, initialTasks: tasks }));
      }).catch(err => {
        dispatch(simulationError(String(err)));
      });
    }
  }, [projectStatus, currentProject, projectId, simStatus, dispatch, tasks]);

  // Poll simulation status until completed, then fetch results
  useEffect(() => {
    if (!simulationId) return;
    const interval = setInterval(async () => {
      try {
        const status = await api.getSimulationStatus(simulationId);
        if (status.status === 'completed' || status.status === 'failed') {
          clearInterval(interval);
          setPolling(null);
          dispatch(fetchSimulationResult(simulationId));
        }
      } catch (err) {
        console.error('Failed to poll simulation status', err);
        dispatch(simulationError('Simulation status polling failed'));
      }
    }, 1000);
    setPolling(interval);
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [simulationId, dispatch]);

  // WebSocket subscription to backend events
  const { events: wsEvents } = useWebSocket(simulationId ? String(simulationId) : null);
  useEffect(() => {
    wsEvents.forEach(ev => {
      dispatch(pushEvent({
        type: (ev.event_type as any) || 'SIM_START',
        event_type: ev.event_type,
        timestamp: ev.timestamp,
        task_id: ev.task_id,
        risk_id: ev.risk_id,
        details: ev.details,
        message: ev.event_type,
      }));
      dispatch(applyTaskEvent({
        type: ev.event_type as any,
        event_type: ev.event_type,
        timestamp: ev.timestamp,
        task_id: ev.task_id,
        risk_id: ev.risk_id,
        details: ev.details,
      }));
    });
  }, [wsEvents, dispatch]);

  const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  if (projectStatus === 'loading' || !currentProject) {
    return <Typography sx={{ p: 4 }}>Loading Project for Simulation...</Typography>;
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: 'calc(100vh - 64px)' }}>
      <SimulationControls />
      
      <Box sx={{ height: '65%', p: 1, pt: 0 }}>
        <Paper elevation={2} sx={{ height: '100%', width: '100%' }}>
            <GanttPanel tasksOverride={simTasks.length ? simTasks : tasks} />
        </Paper>
      </Box>

      <Box sx={{ height: '35%' }}>
        <Paper elevation={2} sx={{ m: 1, mt: 0, height: 'calc(100% - 8px)' }}>
            <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
                <Tabs value={tabValue} onChange={handleTabChange} aria-label="Simulation tabs">
                    <Tab label="KPI Dashboard" id="sim-tab-0" aria-controls="sim-panel-0" />
                    <Tab label="Event Log" id="sim-tab-1" aria-controls="sim-panel-1" />
                </Tabs>
            </Box>
            <Box sx={{ height: 'calc(100% - 49px)' }}>
              <TabPanel value={tabValue} index={0}>
                  <KpiDashboard />
              </TabPanel>
              <TabPanel value={tabValue} index={1}>
                  <EventLog />
              </TabPanel>
            </Box>
        </Paper>
      </Box>
    </Box>
  );
};
export default SimulationPage;

import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { SimulationEvent, KpiValues, Task } from '../types/domain';

export type SimulationStatus = 'idle' | 'running' | 'paused' | 'finished' | 'error';

// This will hold the dynamic state of a task during simulation
export type SimTaskState = Task;

export interface SimulationState {
  status: SimulationStatus;
  simulationId: number | null;
  currentDay: number;
  speed: number; // 1x, 2x, 4x
  events: SimulationEvent[];
  kpis: KpiValues;
  tasks: SimTaskState[]; // Add tasks to simulation state
  error: string | null;
  kpiHistory: { day: number; sv: number; cv: number }[];
}

const initialState: SimulationState = {
  status: 'idle',
  simulationId: null,
  currentDay: 0,
  speed: 1,
  events: [],
  kpis: { pv: 0, ev: 0, ac: 0, sv: 0, cv: 0, rei: 0 },
  tasks: [],
  error: null,
  kpiHistory: [],
};

const simulationSlice = createSlice({
  name: 'simulation',
  initialState,
  reducers: {
    startSimulation(state, action: PayloadAction<{ simulationId: number; initialTasks: Task[] }>) {
      state.status = 'running';
      state.simulationId = action.payload.simulationId;
      state.tasks = action.payload.initialTasks;
      state.currentDay = 0;
      state.events = [];
    },
    pauseSimulation(state) {
      if (state.status === 'running') {
        state.status = 'paused';
      }
    },
    resumeSimulation(state) {
      if (state.status === 'paused') {
        state.status = 'running';
      }
    },
    stopSimulation(state) {
      state.status = 'finished';
      state.events.push({
        timestamp: Date.now(),
        type: 'SIM_END',
        message: 'Simulation stopped by user.'
      });
    },
    setSimulationSpeed(state, action: PayloadAction<number>) {
      state.speed = action.payload;
    },
    pushEvent(state, action: PayloadAction<SimulationEvent>) {
      const normalizedType = (action.payload.event_type as any) || action.payload.type || 'event';
      state.events = [...state.events.slice(-199), { ...action.payload, type: normalizedType }];
      if (normalizedType === 'SIM_END' || normalizedType === 'simulation_completed') {
        state.status = 'finished';
      }
    },
      applyTaskEvent(state, action: PayloadAction<SimulationEvent>) {
        const evt = action.payload;
        if (!state.tasks.length) return;
  
        const normalizedType = evt.event_type || evt.type;
        
        const tasks = state.tasks.map(t => {
          // Handle explicit task events
          if (evt.task_id === t.id) {
              if (normalizedType === 'task_started') {
                  return { ...t, progress: 0 };
              }
              if (normalizedType === 'task_completed') {
                  return { ...t, progress: 1 };
              }
          }
  
          // Handle day_advanced for active tasks
          if (normalizedType === 'day_advanced') {
              const activeTasks = (evt.details?.active_tasks as number[]) || [];
              if (activeTasks.includes(t.id)) {
                  const duration = t.duration || 1;
                  // Increment progress, but cap at 0.99 until explicitly completed
                  const increment = 1 / duration;
                  const nextProgress = Math.min(0.99, (t.progress ?? 0) + increment);
                  return { ...t, progress: nextProgress };
              }
          }
          
          return t;
        });
        state.tasks = tasks;
        
        if (normalizedType === 'simulation_completed') {
          state.status = 'finished';
        }
      },
  
    tick(state, action: PayloadAction<{ day: number; kpis: KpiValues; newEvents: SimulationEvent[]; updatedTasks: SimTaskState[] }>) {
      if (state.status !== 'running') return;
      state.currentDay = action.payload.day;
      state.kpis = action.payload.kpis;
      state.events = [...state.events, ...action.payload.newEvents].slice(-200);
      state.tasks = action.payload.updatedTasks;
      state.kpiHistory = [...state.kpiHistory, { day: action.payload.day, sv: action.payload.kpis.sv, cv: action.payload.kpis.cv }].slice(-200);
    },
    simulationError(state, action: PayloadAction<string>) {
        state.status = 'error';
        state.error = action.payload;
    }
  },
});

export const {
  startSimulation,
  pauseSimulation,
  resumeSimulation,
  stopSimulation,
  setSimulationSpeed,
  pushEvent,
  applyTaskEvent,
  tick,
  simulationError,
} = simulationSlice.actions;

export default simulationSlice.reducer;

