import React, { useMemo, useState } from 'react';
import { Box, Chip, Stack, Tooltip, Typography, Slider, Button } from '@mui/material';
import WarningAmberIcon from '@mui/icons-material/WarningAmber';
import { useAppSelector } from '../../store/hooks';
import { Risk, Task } from '../../types/domain';

type BarTask = Task & { affectedByRisk?: Risk[] };
const MS_PER_DAY = 86400000;

const computeCriticalPath = (tasks: Task[]): Set<number> => { // Return Set<number>
  if (!tasks.length) return new Set<number>();
  const duration = new Map(tasks.map((t) => [t.id, Math.max(0, t.duration)]));
  const preds = new Map(tasks.map((t) => [t.id, t.predecessors]));
  const memo = new Map<number, number>(); // Use number for ID

  const dfs = (id: number): number => { // Use number for ID
    if (memo.has(id)) return memo.get(id)!;
    const bestPred = Math.max(0, ...(preds.get(id) || []).map((p) => dfs(p)));
    const total = bestPred + (duration.get(id) ?? 0);
    memo.set(id, total);
    return total;
  };

  tasks.forEach((t) => dfs(t.id));
  const maxLen = Math.max(0, ...Array.from(memo.values()));
  const critical = new Set<number>(); // Use number for ID
  memo.forEach((len, id) => {
    if (len === maxLen) critical.add(id);
  });
  return critical;
};

// Compute timeline bounds
const getBounds = (tasks: Task[]) => {
  if (!tasks.length) return { min: new Date(), max: new Date(), totalDays: 1 };
  const starts = tasks.map((t) => new Date(t.start_date).getTime());
  const min = Math.min(...starts);
  const max = Math.max(...tasks.map((t) => new Date(t.start_date).getTime() + t.duration * 86400000));
  const totalDays = Math.max(1, Math.ceil((max - min) / MS_PER_DAY));
  return { min: new Date(min), max: new Date(max), totalDays };
};

interface Props {
  tasksOverride?: Task[];
}

const GanttPanel: React.FC<Props> = ({ tasksOverride }) => {
  const { tasks: baseTasks, risks } = useAppSelector((state) => state.projects);
  const [zoom, setZoom] = useState<number>(1); // 0.5x, 1x, 2x
  const [showGrid] = useState(true);

  const tasks: BarTask[] = useMemo(() => {
    const source = tasksOverride && tasksOverride.length ? tasksOverride : (baseTasks || []);
    return source.map((t) => ({
      ...t,
      predecessors: t.predecessors || [],
      progress: t.progress ?? 0,
      affectedByRisk: risks.filter((r) => r.affected_task_ids?.includes(t.id)),
    }));
  }, [baseTasks, risks, tasksOverride]);

  const criticalIds = useMemo(() => computeCriticalPath(tasks), [tasks]);
  const { min, totalDays } = useMemo(() => getBounds(tasks), [tasks]);

  const baseDayWidth = 14; // px per day
  const dayWidth = Math.max(6, baseDayWidth * zoom);

  const renderBar = (task: BarTask) => {
    const startOffset = Math.max(
      0,
      Math.round((new Date(task.start_date).getTime() - min.getTime()) / MS_PER_DAY),
    );
    const width = Math.max(6, task.duration * dayWidth);
    const left = startOffset * dayWidth;
    const progressWidth = Math.min(width, Math.max(0, Math.round(width * (task.progress ?? 0))));
    const isMilestone = task.duration === 0;
    const hasRisk = task.affectedByRisk && task.affectedByRisk.length > 0;
    const isCritical = criticalIds.has(task.id);
    const riskSeverity = task.affectedByRisk?.reduce((acc, r) => acc + r.cost_impact * r.probability, 0) ?? 0;

    return (
      <Box
        key={task.id}
        sx={{
          position: 'relative',
          pl: 1 + (task.parent ? 2 : 0),
          py: 0.5,
          borderBottom: '1px solid',
          borderColor: 'divider',
        }}
      >
        <Typography variant="body2" sx={{ mb: 0.5 }}>
          {task.text}
        </Typography>
        <Box sx={{ position: 'relative', height: 18, backgroundColor: 'action.hover' }}>
          <Box
            aria-label={`Task ${task.text}`}
            sx={{
              position: 'absolute',
              left,
              top: 0,
              height: 18,
              width: isMilestone ? 10 : width,
              bgcolor: isCritical ? 'error.light' : riskSeverity > 40000 ? 'warning.light' : 'primary.light',
              borderRadius: 0.5,
              outline: isCritical ? '2px solid #D32F2F' : 'none',
            }}
          >
            {!isMilestone && (
            <Box
              sx={{
                height: '100%',
                width: progressWidth,
                bgcolor: isCritical ? 'error.main' : 'primary.main',
                borderRadius: 0.5,
                transition: 'width 0.2s ease',
                opacity: riskSeverity > 40000 ? 0.9 : 1,
              }}
            />
            )}
          </Box>
          {hasRisk && (
            <Stack direction="row" spacing={0.5} sx={{ position: 'absolute', right: 4, top: -6 }}>
              {task.affectedByRisk?.slice(0, 2).map((r) => (
                <Tooltip key={r.id} title={`Risk: ${r.description}`}>
                  <WarningAmberIcon color="warning" fontSize="small" />
                </Tooltip>
              ))}
              {task.affectedByRisk && task.affectedByRisk.length > 2 && (
                <Chip size="small" label={`+${task.affectedByRisk.length - 2}`} />
              )}
            </Stack>
          )}
        </Box>
        <Stack direction="row" spacing={1} sx={{ mt: 0.25 }}>
          <Chip size="small" label={`Start: ${task.start_date}`} />
          <Chip size="small" label={`Dur: ${task.duration}d`} />
          {task.predecessors.length > 0 && (
            <Chip size="small" label={`Pred: ${task.predecessors.join(', ')}`} />
          )}
        </Stack>
      </Box>
    );
  };

  return (
    <Box sx={{ width: '100%', height: '100%', overflowX: 'auto', overflowY: 'auto', p: 1 }}>
      <Stack direction="row" spacing={2} alignItems="center" sx={{ mb: 1 }}>
        <Typography variant="h6">Timeline</Typography>
        <Box sx={{ width: 160 }}>
          <Slider
            aria-label="Zoom"
            size="small"
            min={0.5}
            max={2}
            step={0.25}
            value={zoom}
            valueLabelDisplay="auto"
            onChange={(_e, val) => setZoom(val as number)}
          />
        </Box>
        <Button size="small" variant="outlined" onClick={() => setZoom(1)}>
          Reset zoom
        </Button>
      </Stack>
      <Box
        role="presentation"
        aria-label="Gantt timeline"
        sx={{
          position: 'relative',
          minWidth: totalDays * dayWidth + 120,
          border: '1px solid',
          borderColor: 'divider',
          borderRadius: 1,
          bgcolor: 'background.paper',
        }}
      >
        {/* Day scale */}
        <Box sx={{ display: 'flex', position: 'sticky', top: 0, zIndex: 1, bgcolor: 'background.paper' }}>
          {Array.from({ length: totalDays }).map((_, idx) => (
            <Box
              key={idx}
              sx={{
                width: dayWidth,
                height: 24,
                borderRight: showGrid ? '1px solid' : 'none',
                borderColor: showGrid ? 'divider' : 'transparent',
                fontSize: 10,
                color: 'text.secondary',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              {idx + 1}
            </Box>
          ))}
        </Box>
        {/* Bars */}
        <Box>{tasks.map(renderBar)}</Box>
      </Box>
      <Stack direction="row" spacing={2} sx={{ mt: 1, flexWrap: 'wrap' }}>
        <Chip label="Critical path" color="error" variant="outlined" />
        <Chip label="High risk impact" icon={<WarningAmberIcon color="warning" />} variant="outlined" />
        <Chip label="Zoom: scroll/slider; Reset to 1x" />
      </Stack>
    </Box>
  );
};

export default GanttPanel;

import React, { useEffect, useState } from 'react';
import { Box, Paper, Typography, Tabs, Tab } from '@mui/material';
import { useParams, useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../store/hooks';
import { fetchProjectDetails } from '../store/projectSlice';
import * as api from '../services/api';
import { startSimulation as startSimAction, pushEvent, applyTaskEvent, simulationError } from '../store/simulationSlice';
import SimulationControls from '../components/simulation/SimulationControls';
import GanttPanel from '../components/simulation/GanttPanel';
import KpiDashboard from '../components/simulation/KpiDashboard';
import EventLog from '../components/simulation/EventLog';
import { useWebSocket } from '../services/websocket';
import { fetchSimulationResult } from '../store/projectSlice';

// (TabPanel component remains the same)
interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;
  return (
    <div role="tabpanel" hidden={value !== index} {...other}>
      {value === index && <Box sx={{ p: 2, height: '100%', overflowY: 'auto' }}>{children}</Box>}
    </div>
  );
}

const SimulationPage: React.FC = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { currentProject, tasks, status: projectStatus } = useAppSelector((state) => state.projects);
  const simStatus = useAppSelector(state => state.simulation.status);
  const simTasks = useAppSelector(state => state.simulation.tasks);
  const [tabValue, setTabValue] = useState(0);
  const simulationId = useAppSelector(state => state.simulation.simulationId);
  const [, setPolling] = useState<ReturnType<typeof setInterval> | null>(null);

  // Effect to fetch initial data
  useEffect(() => {
    if (!projectId) {
      navigate('/');
      return;
    }
    const numericId = Number(projectId);
    if (!currentProject || currentProject.id !== numericId) {
      dispatch(fetchProjectDetails(numericId));
    }
  }, [projectId, dispatch, navigate, currentProject]);

  // Effect to auto-start simulation once project is loaded
  useEffect(() => {
     const numericId = projectId ? Number(projectId) : null;
     if (projectStatus === 'succeeded' && numericId !== null && currentProject?.id === numericId && simStatus === 'idle') {
      api.runSimulation(numericId).then(res => {
        dispatch(startSimAction({ simulationId: res.simulation_run_id, initialTasks: tasks }));
      }).catch(err => {
        dispatch(simulationError(String(err)));
      });
    }
  }, [projectStatus, currentProject, projectId, simStatus, dispatch, tasks]);

  // Poll simulation status until completed, then fetch results
  useEffect(() => {
    if (!simulationId) return;
    const interval = setInterval(async () => {
      try {
        const status = await api.getSimulationStatus(simulationId);
        if (status.status === 'completed' || status.status === 'failed') {
          clearInterval(interval);
          setPolling(null);
          dispatch(fetchSimulationResult(simulationId));
        }
      } catch (err) {
        console.error('Failed to poll simulation status', err);
        dispatch(simulationError('Simulation status polling failed'));
      }
    }, 1000);
    setPolling(interval);
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [simulationId, dispatch]);

  // WebSocket subscription to backend events
  const { events: wsEvents } = useWebSocket(simulationId ? String(simulationId) : null);
  useEffect(() => {
    wsEvents.forEach(ev => {
      dispatch(pushEvent({
        type: (ev.event_type as any) || 'SIM_START',
        event_type: ev.event_type,
        timestamp: ev.timestamp,
        task_id: ev.task_id,
        risk_id: ev.risk_id,
        details: ev.details,
        message: ev.event_type,
      }));
      dispatch(applyTaskEvent({
        type: ev.event_type as any,
        event_type: ev.event_type,
        timestamp: ev.timestamp,
        task_id: ev.task_id,
        risk_id: ev.risk_id,
        details: ev.details,
      }));
    });
  }, [wsEvents, dispatch]);

  const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  if (projectStatus === 'loading' || !currentProject) {
    return <Typography sx={{ p: 4 }}>Loading Project for Simulation...</Typography>;
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: 'calc(100vh - 64px)' }}>
      <SimulationControls />
      
      <Box sx={{ height: '65%', p: 1, pt: 0 }}>
        <Paper elevation={2} sx={{ height: '100%', width: '100%' }}>
            <GanttPanel tasksOverride={simTasks.length ? simTasks : tasks} />
        </Paper>
      </Box>

      <Box sx={{ height: '35%' }}>
        <Paper elevation={2} sx={{ m: 1, mt: 0, height: 'calc(100% - 8px)' }}>
            <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
                <Tabs value={tabValue} onChange={handleTabChange} aria-label="Simulation tabs">
                    <Tab label="KPI Dashboard" id="sim-tab-0" aria-controls="sim-panel-0" />
                    <Tab label="Event Log" id="sim-tab-1" aria-controls="sim-panel-1" />
                </Tabs>
            </Box>
            <Box sx={{ height: 'calc(100% - 49px)' }}>
              <TabPanel value={tabValue} index={0}>
                  <KpiDashboard />
              </TabPanel>
              <TabPanel value={tabValue} index={1}>
                  <EventLog />
              </TabPanel>
            </Box>
        </Paper>
      </Box>
    </Box>
  );
};
