                        placeholder="E.g. Foundation pour"
                        InputProps={{ sx: { fontSize: 14, py: 1 } }}
                        onChange={(e) => setDraftValue(task.id, 'text', e.target.value)}
                        onBlur={() => commitDraftValue(task.id, 'text')}
                        disabled={isLoading_}
                      />
