                        displayEmpty
                        aria-label={`Resource for ${task.text}`}
                        onChange={(e) => {
                          const val = e.target.value === '' ? undefined : Number(e.target.value);
                          setDraftValue(task.id, 'resource_id', val);
                          if (val !== undefined) commitDraftValue(task.id, 'resource_id');
