  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { currentProject, tasks, status: projectStatus } = useAppSelector((state) => state.projects);
  const simStatus = useAppSelector(state => state.simulation.status);
  const simTasks = useAppSelector(state => state.simulation.tasks);
  const [tabValue, setTabValue] = useState(0);
  const simulationId = useAppSelector(state => state.simulation.simulationId);
  const [, setPolling] = useState<ReturnType<typeof setInterval> | null>(null);

  // Effect to fetch initial data
  useEffect(() => {
    if (!projectId) {
      navigate('/');
      return;
    }
    const numericId = Number(projectId);
    if (!currentProject || currentProject.id !== numericId) {
      dispatch(fetchProjectDetails(numericId));
    }
  }, [projectId, dispatch, navigate, currentProject]);

  // Effect to auto-start simulation once project is loaded
  useEffect(() => {
     const numericId = projectId ? Number(projectId) : null;
     if (projectStatus === 'succeeded' && numericId !== null && currentProject?.id === numericId && simStatus === 'idle') {
      api.runSimulation(numericId).then(res => {
        dispatch(startSimAction({ simulationId: res.simulation_run_id, initialTasks: tasks }));
      }).catch(err => {
        dispatch(simulationError(String(err)));
      });
    }
  }, [projectStatus, currentProject, projectId, simStatus, dispatch, tasks]);

  // Poll simulation status until completed, then fetch results
  useEffect(() => {
    if (!simulationId) return;
    const interval = setInterval(async () => {
      try {
        const status = await api.getSimulationStatus(simulationId);
        if (status.status === 'completed' || status.status === 'failed') {
          clearInterval(interval);
          setPolling(null);
          dispatch(fetchSimulationResult(simulationId));
        }
      } catch (err) {
        console.error('Failed to poll simulation status', err);
        dispatch(simulationError('Simulation status polling failed'));
      }
    }, 1000);
    setPolling(interval);
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [simulationId, dispatch]);

  // WebSocket subscription to backend events
  const { events: wsEvents } = useWebSocket(simulationId ? String(simulationId) : null);
  useEffect(() => {
    wsEvents.forEach(ev => {
      dispatch(pushEvent({
        type: (ev.event_type as any) || 'SIM_START',
        event_type: ev.event_type,
        timestamp: ev.timestamp,
        task_id: ev.task_id,
        risk_id: ev.risk_id,
        details: ev.details,
        message: ev.event_type,
      }));
      dispatch(applyTaskEvent({
        type: ev.event_type as any,
        event_type: ev.event_type,
        timestamp: ev.timestamp,
        task_id: ev.task_id,
        risk_id: ev.risk_id,
        details: ev.details,
      }));
    });
  }, [wsEvents, dispatch]);

  const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  if (projectStatus === 'loading' || !currentProject) {
    return <Typography sx={{ p: 4 }}>Loading Project for Simulation...</Typography>;
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: 'calc(100vh - 64px)' }}>
      <SimulationControls />
      
      <Box sx={{ height: '65%', p: 1, pt: 0 }}>
        <Paper elevation={2} sx={{ height: '100%', width: '100%' }}>
            <GanttPanel tasksOverride={simTasks.length ? simTasks : tasks} />
        </Paper>
      </Box>

      <Box sx={{ height: '35%' }}>
        <Paper elevation={2} sx={{ m: 1, mt: 0, height: 'calc(100% - 8px)' }}>
            <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
                <Tabs value={tabValue} onChange={handleTabChange} aria-label="Simulation tabs">
                    <Tab label="KPI Dashboard" id="sim-tab-0" aria-controls="sim-panel-0" />
                    <Tab label="Event Log" id="sim-tab-1" aria-controls="sim-panel-1" />
                </Tabs>
            </Box>
            <Box sx={{ height: 'calc(100% - 49px)' }}>
              <TabPanel value={tabValue} index={0}>
                  <KpiDashboard />
              </TabPanel>
              <TabPanel value={tabValue} index={1}>
                  <EventLog />
              </TabPanel>
            </Box>
        </Paper>
      </Box>
    </Box>
  );
};
export default SimulationPage;

import React from 'react';
import { Typography, Box, Card, CardContent, Grid, Alert } from '@mui/material';
import { useAppSelector } from '../../store/hooks';

const KpiCard: React.FC<{ title: string; value: string; color?: string, description?: string }> = ({ title, value, color, description }) => (
    <Card elevation={3} sx={{ height: '100%' }}>
        <CardContent>
            <Typography color="text.secondary" gutterBottom>{title}</Typography>
            <Typography variant="h4" component="div" sx={{ color: color || 'text.primary' }}>
                {value}
            </Typography>
            {description && <Typography variant="body2" color="text.secondary">{description}</Typography>}
        </CardContent>
    </Card>
);

const KpiDashboard: React.FC = () => {
  const { simulationResult, currentProject } = useAppSelector(state => state.projects);
  const simEvents = useAppSelector(state => state.simulation.events);

  const formatCurrency = (value: number) => {
    if (typeof value !== 'number' || isNaN(value)) return '$0';
    return `$${Math.round(value).toLocaleString()}`;
  };

  if (!currentProject) {
    return <Typography>Select a project to see KPIs.</Typography>;
  }

  const budget = currentProject.budget;
  const taskCompletedCost = simEvents
    .filter(e => e.event_type === 'task_completed' && typeof e.details?.cost === 'number')
    .reduce((sum, e) => sum + (e.details?.cost as number), 0);
  const lastDayEvent = simEvents.find(e => e.event_type === 'day_advanced');
  const liveDuration = (lastDayEvent?.details as any)?.day || 0;

  const totalCost = simulationResult?.total_cost ?? taskCompletedCost;
  const totalDuration = simulationResult?.total_duration ?? liveDuration;
  const tasksCompleted = simulationResult?.tasks_completed ?? simEvents.filter(e => e.event_type === 'task_completed').length;
  const riskEvents = simulationResult?.risk_events ?? simEvents.filter(e => e.event_type === 'risk_triggered').length;
  const baseDuration = simulationResult?.base_duration ?? undefined;
  const criticalPath = simulationResult?.critical_path ?? [];
  const overrun = totalCost - budget;

  if (!simulationResult && simEvents.length === 0) {
    return (
        <Alert severity="info">Run a simulation to view Key Performance Indicators.</Alert>
    );
  }

  return (
    <Box>
      <Typography variant="h6" gutterBottom>Key Performance Indicators</Typography>
      <Grid container spacing={2}>
        <Grid item xs={12} sm={6} md={3}>
            <KpiCard title="Project Budget" value={formatCurrency(budget)} />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
            <KpiCard title="Total Cost" value={formatCurrency(totalCost)} description="Includes risk impacts when present." color={totalCost > budget ? 'error.main' : 'success.main'} />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
            <KpiCard 
              title="Duration (days)" 
              value={totalDuration?.toString() || '0'} 
              description={baseDuration ? `Base CPM: ${baseDuration} days` : 'Live estimate'}
            />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
            <KpiCard 
              title="Cost Overrun" 
              value={formatCurrency(overrun)} 
              description="Difference between total cost and budget."
              color={overrun > 0 ? 'error.main' : 'text.primary'}
            />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
            <KpiCard title="Tasks Completed" value={tasksCompleted.toString()} description="Completed during this run." />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
            <KpiCard title="Risk Events" value={riskEvents.toString()} description="Triggered during this run." color={riskEvents > 0 ? 'warning.main' : 'success.main'} />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
            <KpiCard title="Critical Path" value={criticalPath.join(' → ') || 'N/A'} description="From CPM baseline." />
        </Grid>
      </Grid>
    </Box>
  );
};

