@app.post("/projects/{project_id}/calculate-cpm/", tags=["Simulation"])
def calculate_project_cpm(project_id: int, db: Session = Depends(get_db)):
    """
    Calculate the Critical Path Method for a project.
    Returns critical path, project duration, and task schedules.
    """
    project = crud.get_project(db, project_id=project_id)
    if project is None:
        raise HTTPException(status_code=404, detail="Project not found")
    
    # Get all tasks for the project
    tasks = crud.get_tasks(db, project_id=project_id, skip=0, limit=1000)
    
    if not tasks:
        raise HTTPException(status_code=400, detail="Project has no tasks")
    
    # Prepare task data for CPM
    task_data = [CPMTask(id=t.id, duration=t.duration, dependencies=t.dependencies or [], cost=t.cost or 0.0) for t in tasks]

    try:
        result = calculate_cpm(task_data)
        return result
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"CPM calculation error: {str(e)}")


@app.websocket("/ws/simulations/{simulation_id}/events")
async def websocket_simulation_events(websocket: WebSocket, simulation_id: int, db: Session = Depends(get_db)):
    """
    WebSocket endpoint for receiving simulation events in real-time.
    
    Clients connect with: ws://localhost:8001/ws/simulations/{simulation_id}/events
    
    Server sends events like:
    {
        "event_type": "task_started",
        "timestamp": "2025-11-28T17:00:00",
        "task_id": 1,
        "details": {}
    }
    
    Clients can send:
    {
        "action": "ping"
    }
    """
    # Verify simulation exists
    simulation = crud.get_simulation_run(db, simulation_id)
    if simulation is None:
        await websocket.close(code=404)
        return
    
    await manager.connect(websocket, simulation_id)
    
    # Send connection confirmation
    await websocket.send_json({
        "event_type": "connected",
        "message": f"Connected to simulation {simulation_id}",
        "timestamp": get_timestamp()
    })
    
    try:
        while True:
            # Receive message from client (for keep-alive or commands)
            data = await websocket.receive_json()
            
            if data.get("action") == "ping":
                # Respond to ping
                await websocket.send_json({
                    "event_type": "pong",
                    "timestamp": get_timestamp()
                })
            elif data.get("action") == "subscribe_updates":
                # Send last event log entries as initial data
                events = crud.get_event_logs(db, simulation_id, skip=0, limit=50)
                for event in events:
                    await websocket.send_json({
                        "event_type": event.event_type,
                        "timestamp": event.timestamp.isoformat(),
                        "task_id": event.task_id,
                        "risk_id": event.risk_id,
                        "details": event.details or {}
                    })
    
    except WebSocketDisconnect:
        manager.disconnect(simulation_id, websocket)
    except Exception as e:
        manager.disconnect(simulation_id, websocket)
        print(f"WebSocket error: {e}")


def get_timestamp():
    """Get current timestamp in ISO format (UTC, timezone-aware)."""
    return datetime.now(timezone.utc).isoformat()


@app.post("/simulations/{simulation_id}/broadcast-event/", tags=["Simulation"])
async def broadcast_event(
    simulation_id: int,
    event: schemas.EventLogCreate,
    db: Session = Depends(get_db)
):
    """
    Broadcast an event to all connected WebSocket clients for a simulation.
    This is used by the simulation engine to push events in real-time.
    """
    # Verify simulation exists
    simulation = crud.get_simulation_run(db, simulation_id)
    if simulation is None:
        raise HTTPException(status_code=404, detail="Simulation not found")
    
    # Save event to database
    db_event = crud.create_event_log(db, event, simulation_id)
    
    # Broadcast to connected clients
    await manager.broadcast(simulation_id, {
        "event_type": event.event_type,
        "timestamp": db_event.timestamp.isoformat(),
        "task_id": event.task_id,
        "risk_id": event.risk_id,
        "details": event.details or {}
    })
    
    return {"status": "event_broadcasted", "event_id": db_event.id}


@app.post("/projects/{project_id}/simulate", tags=["Simulation"])
async def start_simulation_background(
    project_id: int,
    background_tasks: BackgroundTasks,
    simulation_run_id: int | None = None,
    run_in_background: bool = True,
    db: Session = Depends(get_db),
):
    """Start a simulation in the background."""
    project = crud.get_project(db, project_id=project_id)
    if project is None:
        raise HTTPException(status_code=404, detail="Project not found")

    if simulation_run_id:
        sim = crud.get_simulation_run(db, simulation_run_id)
        if sim is None:
            raise HTTPException(status_code=404, detail="Simulation run not found")
        target_id = simulation_run_id
    else:
        sim = crud.create_simulation_run(db, project_id, schemas.SimulationRunCreate(seed=None))
        target_id = sim.id

    if run_in_background:
        background_tasks.add_task(run_simulation, db, target_id)
        return JSONResponse(status_code=202, content={"message": "Simulation started in the background. Check back later for results.", "simulation_run_id": target_id})
    else:
        await run_simulation(db, target_id)
        return {"message": "Simulation finished.", "simulation_run_id": target_id}


@app.get("/simulations/{simulation_run_id}/status", response_model=schemas.SimulationRun, tags=["Simulations"])
def get_simulation_status(simulation_run_id: int, db: Session = Depends(get_db)):
    sim = crud.get_simulation_run(db, simulation_run_id=simulation_run_id)
    if sim is None:
        raise HTTPException(status_code=404, detail="Simulation run not found")
    return sim

import { Project, Task, Resource, Risk, SimulationRun, SimulationResults } from '../types/domain';
import { ProjectCreate, ProjectUpdate, TaskCreate, RiskCreate } from '../types/api';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8001';

export interface SimulationStatusResponse extends SimulationRun {}

export interface SimulationEvent {
  event_type: string;
  timestamp: string;
  task_id?: number;
  risk_id?: number;
  details?: Record<string, unknown>;
}

export interface AiInsights {
  overallAssessment: string;
  keyIssues: { id: string; text: string }[];
  actionableRecommendations: { id: string; text: string }[];
}

const API_LATENCY = 500; // ms

// --- Helper to simulate network delay ---
const withDelay = <T>(data: T): Promise<T> => new Promise(resolve => setTimeout(() => resolve(data), API_LATENCY));

// --- API Functions ---

/**
 * Fetches a list of all available projects.
 * Corresponds to: GET /projects
 */
export const getProjects = async (): Promise<Project[]> => {
  console.log('API: Fetching all projects...');
  const response = await fetch(`${API_BASE_URL}/projects/`);
  if (!response.ok) {
    throw new Error('Failed to fetch projects');
  }
  return response.json();
};

/**
 * Creates a new project.
 * Corresponds to: POST /projects/
 */
export const createProject = async (projectData: ProjectCreate): Promise<Project> => {
  console.log('API: Creating new project...');
  const response = await fetch(`${API_BASE_URL}/projects/`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(projectData),
  });
  if (!response.ok) {
    throw new Error('Failed to create project');
  }
  return response.json();
};

/**
 * Deletes a project.
 * Corresponds to: DELETE /projects/{project_id}
 */
export const deleteProject = async (projectId: number): Promise<void> => {
  console.log(`API: Deleting project ${projectId}...`);
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}`, {
    method: 'DELETE',
  });
  if (!response.ok) {
    throw new Error('Failed to delete project');
  }
};

/**
 * Updates an existing project.
 * Corresponds to: PATCH /projects/{project_id}
 */
export const updateProject = async (projectId: number, data: ProjectUpdate): Promise<Project> => {
  console.log(`API: Updating project ${projectId}...`);
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(data),
  });
  if (!response.ok) {
    throw new Error('Failed to update project');
  }
  return response.json();
};


/**
 * Fetches all details for a single project.
 * This function now makes real API calls for project and tasks,
 * but returns mock data for resources and risks.
 */
export const getProjectDetails = async (projectId: number): Promise<{ project: Project; tasks: Task[]; resources: Resource[]; risks: Risk[] }> => {
  console.log(`API: Fetching details for project ${projectId}...`);

  const projectPromise = fetch(`${API_BASE_URL}/projects/${projectId}`);
  const tasksPromise = fetch(`${API_BASE_URL}/projects/${projectId}/tasks/`);
  const risksPromise = fetch(`${API_BASE_URL}/projects/${projectId}/risks/`);
  const resourcesPromise = fetch(`${API_BASE_URL}/projects/${projectId}/resources/`);

  const [projectResponse, tasksResponse, risksResponse, resourcesResponse] = await Promise.all([projectPromise, tasksPromise, risksPromise, resourcesPromise]);

  if (!projectResponse.ok) {
    throw new Error('Failed to fetch project details');
  }
  if (!tasksResponse.ok) {
    throw new Error('Failed to fetch tasks for the project');
  }
  if (!risksResponse.ok) {
    throw new Error('Failed to fetch risks for the project');
  }
  if (!resourcesResponse.ok) {
    throw new Error('Failed to fetch resources for the project');
  }

  const project = await projectResponse.json();
  const tasks = await tasksResponse.json();
  const risks = await risksResponse.json();
  const resources = await resourcesResponse.json();

  return {
    project,
    tasks,
    resources,
    risks,
  };
};

/**
 * Creates a new task for a project.
 * Corresponds to: POST /projects/{project_id}/tasks/
 */
export const createTask = async (projectId: number, taskData: TaskCreate): Promise<Task> => {
  console.log(`API: Creating new task for project ${projectId}...`);
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}/tasks/`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(taskData),
  });
  if (!response.ok) {
    throw new Error('Failed to create task');
  }
  return response.json();
};

/**
 * Updates an existing task.
 * Corresponds to: PATCH /tasks/{task_id}
 */
export const updateTask = async (taskId: number, taskData: Partial<TaskCreate>): Promise<Task> => {
  console.log(`API: Updating task ${taskId}...`);
  const response = await fetch(`${API_BASE_URL}/tasks/${taskId}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
    },
